programs.challenge2:
def double(number):
    return number * 2
def square(number):
    return number * number
def half(number):
    return number / 2
print("1: double\n2: square\n3: half")
choice = input("Choice: ")
value = int(input("Number: "))
if choice == "1":
    print("Result:", double(value))
elif choice == "2":
    print("Result:", square(value))
elif choice == "3":
    print("Result:", half(value))
else:
    print("Invalid choice.")

programs.challenge3:
def show_menu():
    print("1: area, 2: perimeter")
def area(length, width):
    return length * width
def perimeter(length, width):
    return 2 * length + 2 * width
show_menu()
choice = input("Choice: ")
length = float(input("Length: "))
width = float(input("Width: "))
if choice == "1":
    print("Area:", area(length, width))
elif choice == "2":
    print("Perimeter:", perimeter(length, width))
else:
    print("Invalid choice.")
